package com.biocircular.compostaje.service;
import com.biocircular.compostaje.dto.*; import com.biocircular.compostaje.entity.*; import com.biocircular.compostaje.exception.BusinessException; import com.biocircular.compostaje.mapper.CompostajeMapper; import com.biocircular.compostaje.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*; import java.util.stream.*;
@Service @Transactional public class CompostajeService {
 private final TipoResiduoRepository tipos; private final EtapaRepository etapas; private final IngresoResiduoRepository ingresos; private final LoteRepository lotes; private final LoteEtapaRepository loteEtapas; private final ObservacionRepository observaciones; private final CompostRepository composts; private final MovimientoRepository movimientos; private final RemoteAuditService remote;
 public CompostajeService(TipoResiduoRepository a,EtapaRepository b,IngresoResiduoRepository c,LoteRepository d,LoteEtapaRepository e,ObservacionRepository f,CompostRepository g,MovimientoRepository h,RemoteAuditService i){tipos=a;etapas=b;ingresos=c;lotes=d;loteEtapas=e;observaciones=f;composts=g;movimientos=h;remote=i;}
 @Transactional(readOnly=true) public List<Responses.TipoResiduo> tipos(){return tipos.findAll().stream().map(CompostajeMapper::tipo).toList();} public Responses.TipoResiduo crearTipo(Requests.TipoResiduo r){if(tipos.existsByCodigo(r.codigo()))throw new BusinessException("El código de residuo ya existe"); TipoResiduo t=new TipoResiduo();t.setCodigo(r.codigo());t.setNombre(r.nombre());t.setDescripcion(r.descripcion());return CompostajeMapper.tipo(tipos.save(t));} public Responses.TipoResiduo actualizarTipo(UUID id,Requests.TipoResiduo r){TipoResiduo t=tipo(id);t.setCodigo(r.codigo());t.setNombre(r.nombre());t.setDescripcion(r.descripcion());return CompostajeMapper.tipo(t);} public void desactivarTipo(UUID id){TipoResiduo t=tipo(id);t.setActivo(false);}
 public Responses.Lote registrarIngreso(Requests.IngresoResiduo r){TipoResiduo t=tipo(r.tipoResiduoId()); IngresoResiduo i=new IngresoResiduo();i.cargar(r.recoleccionExternaId(),t,r.responsableId(),Optional.ofNullable(r.fechaHora()).orElse(OffsetDateTime.now()),r.pesoKg(),r.observacion());ingresos.save(i); Lote l=nuevoLote(r.responsableId(),i.getFechaHora().toLocalDate());l.getIngresos().add(i); iniciarPrimeraEtapa(l,r.responsableId());remote.audit("INGRESO_RESIDUO",l.getId());return CompostajeMapper.lote(l);}
 public Responses.Lote crearLote(Requests.Lote r){Lote l=nuevoLote(r.responsableId(),Optional.ofNullable(r.fechaInicio()).orElse(LocalDate.now()));iniciarPrimeraEtapa(l,r.responsableId());remote.audit("CREACION_LOTE",l.getId());return CompostajeMapper.lote(l);} private Lote nuevoLote(UUID resp,LocalDate fecha){Lote l=new Lote();l.crear("LOT-"+fecha.toString().replace("-","")+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(),fecha,resp);return lotes.save(l);} private void iniciarPrimeraEtapa(Lote l,UUID resp){EtapaCompostaje e=etapas.findFirstByActivoTrueOrderByOrden().orElseThrow(()->new BusinessException("No hay etapas configuradas"));LoteEtapa le=new LoteEtapa();le.iniciar(l,e,resp);loteEtapas.save(le);}
 @Transactional(readOnly=true) public Page<Responses.Ingreso> listarIngresos(UUID tipoId,Pageable p){return ingresos.findAll((root,q,cb)->tipoId==null?null:cb.equal(root.get("tipoResiduo").get("id"),tipoId),p).map(CompostajeMapper::ingreso);} @Transactional(readOnly=true) public Page<Responses.Lote> listarLotes(EstadoLote estado,Pageable p){return lotes.findAll((root,q,cb)->estado==null?null:cb.equal(root.get("estado"),estado),p).map(CompostajeMapper::lote);} @Transactional(readOnly=true) public Responses.Lote lote(UUID id){return CompostajeMapper.lote(loteEntidad(id));} public Responses.Lote cancelarLote(UUID id){Lote l=loteEntidad(id);if(l.getEstado()!=EstadoLote.EN_PROCESO)throw new BusinessException("Solo se pueden cancelar lotes en proceso");l.cancelar();remote.audit("CANCELACION_LOTE",id);return CompostajeMapper.lote(l);}
 public Responses.Etapa agregarEtapa(UUID loteId,Requests.Etapa r){Lote l=loteEntidad(loteId);if(l.getEstado()!=EstadoLote.EN_PROCESO)throw new BusinessException("El lote no está en proceso");if(loteEtapas.existsByLoteIdAndEtapaId(loteId,r.etapaId()))throw new BusinessException("La etapa ya fue registrada"); EtapaCompostaje e=etapas.findById(r.etapaId()).orElseThrow(()->new NoSuchElementException("Etapa no encontrada")); loteEtapas.findByLoteIdOrderByFechaInicio(loteId).stream().filter(x->x.getEstado()==EstadoEtapa.EN_PROCESO).forEach(LoteEtapa::finalizar);LoteEtapa le=new LoteEtapa();le.iniciar(l,e,r.responsableId());loteEtapas.save(le);remote.audit("CAMBIO_ETAPA",loteId);return CompostajeMapper.etapa(le);} public Responses.Etapa finalizarEtapa(UUID id){LoteEtapa le=loteEtapas.findById(id).orElseThrow(()->new NoSuchElementException("Etapa de lote no encontrada"));le.finalizar();remote.audit("FINALIZACION_ETAPA",le.getLote().getId());return CompostajeMapper.etapa(le);}
 public Responses.Observacion observar(UUID loteId,Requests.Observacion r){LoteEtapa le=loteEtapas.findById(r.loteEtapaId()).orElseThrow(()->new NoSuchElementException("Etapa de lote no encontrada"));if(!le.getLote().getId().equals(loteId))throw new BusinessException("La etapa no pertenece al lote");ObservacionEtapa o=new ObservacionEtapa();o.crear(le,r.responsableId(),r.nota());return CompostajeMapper.observacion(observaciones.save(o));}
 public Responses.Compost producir(Requests.Produccion r){Lote l=loteEntidad(r.loteId());if(l.getEstado()!=EstadoLote.EN_PROCESO)throw new BusinessException("El lote no está en proceso");if(composts.findByLoteId(l.getId()).isPresent())throw new BusinessException("El lote ya tiene producción final");loteEtapas.findByLoteIdOrderByFechaInicio(l.getId()).stream().filter(x->x.getEstado()==EstadoEtapa.EN_PROCESO).forEach(LoteEtapa::finalizar);l.cerrar();Compost c=new Compost();c.crear(l,Optional.ofNullable(r.fechaProduccion()).orElse(LocalDate.now()),r.cantidadKg(),r.aptoEntrega());composts.save(c);MovimientoInventario inicial=new MovimientoInventario();inicial.crear(c,TipoMovimiento.INGRESO,r.cantidadKg(),"Producción final del lote",l.getResponsableId());movimientos.save(inicial);remote.audit("PRODUCCION_FINAL",l.getId());remote.reportFinished(l.getId(),r.cantidadKg());return CompostajeMapper.compost(c);}
 public Responses.Movimiento mover(Requests.Movimiento r){Compost c=composts.findById(r.compostId()).orElseThrow(()->new NoSuchElementException("Compost no encontrado"));if(r.tipo()==TipoMovimiento.SALIDA&&saldo(c.getId()).compareTo(r.cantidadKg())<0)throw new BusinessException("Inventario insuficiente");MovimientoInventario m=new MovimientoInventario();m.crear(c,r.tipo(),r.cantidadKg(),r.motivo(),r.usuarioId());movimientos.save(m);remote.audit("MOVIMIENTO_INVENTARIO",c.getLote().getId());return CompostajeMapper.movimiento(m);} @Transactional(readOnly=true) public Responses.Inventario inventario(UUID compostId){return new Responses.Inventario(compostId,saldo(compostId),movimientos.findByCompostIdOrderByFechaHoraDesc(compostId).stream().map(CompostajeMapper::movimiento).toList());} private BigDecimal saldo(UUID compostId){return movimientos.findByCompostIdOrderByFechaHoraDesc(compostId).stream().map(m->m.getTipo()==TipoMovimiento.SALIDA?m.getCantidadKg().negate():m.getCantidadKg()).reduce(BigDecimal.ZERO,BigDecimal::add);}
 @Transactional(readOnly=true) public List<Responses.Compost> compost(){return composts.findAll().stream().map(CompostajeMapper::compost).toList();} @Transactional(readOnly=true) public Responses.Trazabilidad trazabilidad(UUID id){Lote l=loteEntidad(id);Compost c=composts.findByLoteId(id).orElse(null);return new Responses.Trazabilidad(CompostajeMapper.lote(l),loteEtapas.findByLoteIdOrderByFechaInicio(id).stream().map(CompostajeMapper::etapa).toList(),observaciones.findByLoteEtapaLoteIdOrderByFechaHora(id).stream().map(CompostajeMapper::observacion).toList(),c==null?null:CompostajeMapper.compost(c));} @Transactional(readOnly=true) public Responses.Dashboard dashboard(){List<Lote> all=lotes.findAll();BigDecimal in=ingresos.findAll().stream().map(IngresoResiduo::getPesoKg).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal out=composts.findAll().stream().map(Compost::getCantidadKg).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal stock=composts.findAll().stream().map(Compost::getId).map(this::saldo).reduce(BigDecimal.ZERO,BigDecimal::add);return new Responses.Dashboard(all.stream().filter(x->x.getEstado()==EstadoLote.EN_PROCESO).count(),all.stream().filter(x->x.getEstado()==EstadoLote.FINALIZADO).count(),in,out,stock);} private TipoResiduo tipo(UUID id){return tipos.findById(id).orElseThrow(()->new NoSuchElementException("Tipo de residuo no encontrado"));} private Lote loteEntidad(UUID id){return lotes.findWithIngresosById(id).orElseThrow(()->new NoSuchElementException("Lote no encontrado"));}
}
